import os
import re
import pandas as pd
from ace_tools import display_dataframe_to_user

# Directory where uploaded files reside
data_dir = '/mnt/data'

# Define heuristics for tagging
memoir_kw = {
    "museum","cosi","columbus","volunteer","truck","relationship","love","pizza",
    "bar","myspace","job","amnh","boss","mentor","incident","working","diorama",
    "guest","exhibit","internship","chem","burn","run","food","chef","sandwich",
    "cocktail","basement","bookstore","science","demo","gallery","ohio","nyc"
}
fiction_kw = {
    "fiction","story","flash","satire","mutant","character","bent","poughkeepsie",
    "miss","fingertips","hellfire","screenplay","speculative","novel","short","plot"
}
meta_kw = {
    "gpt","chatgpt","analysis","index","timeline","gaps","memoir index","topic list",
    "plan","outline","audit","roadmap","notebooklm"
}

def tag_line(text):
    lower = text.lower()
    if any(k in lower for k in meta_kw):
        return "Meta"
    if any(k in lower for k in fiction_kw):
        return "Fiction"
    if any(k in lower for k in memoir_kw):
        return "Memoir"
    return "Unknown"

def extract_date(text):
    m = re.search(r'(19|20)\d{2}', text)
    if m:
        return m.group(0)
    return ""

rows = []

bullet_prefixes = ('-', '*', '•', '▪', '●')

for filename in os.listdir(data_dir):
    if not filename.endswith('.txt'):
        continue
    filepath = os.path.join(data_dir, filename)
    try:
        with open(filepath, 'r', encoding='utf-8', errors='ignore') as f:
            for line in f:
                stripped = line.strip()
                if not stripped:
                    continue
                is_bullet = stripped.startswith(bullet_prefixes)
                # For certain files treat every non-empty line as a bit
                treat_all = filename.upper().startswith(('TIMELINE','GAPS','INDEX'))
                if is_bullet or treat_all:
                    # Clean bullet marker
                    if is_bullet:
                        bit = stripped.lstrip(''.join(bullet_prefixes)).strip()
                    else:
                        bit = stripped
                    if not bit:
                        continue
                    tag = tag_line(bit)
                    date = extract_date(bit)
                    rows.append({
                        "Bit": bit,
                        "Source_File": filename,
                        "Tag": tag,
                        "Date_BestGuess": date
                    })
    except Exception as e:
        print(f"Error reading {filename}: {e}")

df = pd.DataFrame(rows)
# Sort for convenience
df = df.sort_values(by=["Tag","Source_File"]).reset_index(drop=True)

csv_path = '/mnt/data/bits_tagged.csv'
df.to_csv(csv_path, index=False)

# Display to user
display_dataframe_to_user(name="Tagged Bits", dataframe=df)

csv_path

